	select top 5 * 
	from CMACHYOCLI_MANIANA.dbo.[CLIMPERNAT] AA

	select top 1 * from [KPYMCRECONVEN] CRE (NOLOCK)		
	select top 1 * from [GENMCRECLI] CLI 	
	select top 1 * from CMACHYOCLI_MANIANA.dbo.[CLIMCLIENTES] CLIM 

	--Drop table #t01
	SELECT * into #t01 FROM (
	Select -- top 5 CLIM.dFecIniSisF , CLIM.dFecIniCmac , 
		CLIM.dFecReg , CLIM.cNomCliente, CLIM.cCodSbs,
		CLIM.cCodCliente, ISNULL(cNroDocIde,cNroDocTri) AS 'NroDocumento', CRE.cCodCtaCre,
		CRE.cCreNorRef, CRE.nTasIntCom as 'TasaInteres', CRE.nCosEfeAct as 'TasaCostoEfectivoAnual'
		,CRE.cCodTipCre ,STC.cDesTipCre AS 'TipoCredito',STC.cDesSubTip AS 'SubTipoCredito'
		,CRE.cCodProduc, STC.cDesProCre AS 'ProductoCrediticio',CRE.cCodSubPro	
		,STC.cDesSubcRE AS 'SubProductoCrediticio'
		,EC.cDescriEst AS 'EstadoCredito', (year(getdate()) - year(CLIM.dFecReg)) AS 'Antig'
		 
	From [KPYMCRECONVEN] CRE (NOLOCK)		
	INNER JOIN [GENMCRECLI] CLI 
			ON CLI.cCodCtaCre = CRE.cCodCtaCre
	INNER JOIN CMACHYOCLI_MANIANA.dbo.[CLIMCLIENTES] CLIM 
		    ON CLIM.cCodCliente = CLI.cCodCliente	
	INNER JOIN [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYTSUBTIPCRE] STC
			ON CRE.cCodTipCre = STC.cCodTipCre AND CRE.cCodProduc = STC.cCodProduc 
				AND CRE.cCodSubPro = STC.cCodSubPro and STC.lEstado = '1'	
	INNER JOIN [HYO00402].SOFCMACHYO_DIARIO_MANIANA.dbo.[KPYTEstCreCon] EC 
			ON EC.cEstCreCon = CRE.cEstCreCon	
	WHERE CLIM.dFecReg <= '2015-03-31'
			and CRE.cEstCreCon = 'F'
			and ((year(getdate()) - year(CLIM.dFecReg)) >= 10)
			and ((year(getdate()) - year(CLIM.dFecReg)) <= 25)
			--AND cCodSbs IN ( Select ccodsbs from #t01 )
			and CRE.cCodCtaCre not in  (Select  cCtaCreRef
										From KPYDCREREFINA
										WHERE ccodEstRef = 'R' and cMotCamPla = '3')										
	--ORDER BY CLIM.dFecReg asc  --CLIM.cCodCliente
	) as tmp53
	
	--(25,914 row(s) affected)
	--(25,800 row(s) affected)
			--AND cNroDocIde = '43111949'

	Select 
		* 
	From KPYDCREREFINA
	WHERE ccodEstRef = 'R' and cMotCamPla = '3'

	select * from kpytmotcampla


	select * 
		--cCodCtaCre,
		--round(avg(cast(nDiaVenCuo as float)),0)
	from [KPYDPLANPAGCRE] 
	Where cCodCtaCre = '107002101009243473' -- '107002101008356829'  --'107007101005859831'
	group by cCodCtaCre


	SELECT round(avg(cast(nDiaVenCuo as float)),0)
								FROM [KPYDPLANPAGCRE] PLA (NOLOCK)
								WHERE PLA.cCodCtaCre = @ccodcred 
	--------------------------------------------------------------------------------------


	-------------------------CREDITOS CON PROMEDIO DE ATRASO TABLA PLAN DE PAGOS-----------
	select * from #t01

	ALTER TABLE #t01
	ADD PromDiaAtr int 

	SELECT * into #t02 FROM  ( SELECT * FROM #t01) AS Tmp98
	--DELETE FROM #t02
	--drop table #t02
	SELECT * FROM #t02
	
	--*********************************INDEXANDO****************************************************
	CREATE NONCLUSTERED INDEX #t02_cCodCtaCre_IXN ON #t02(cCodCtaCre)
	CREATE NONCLUSTERED INDEX #t02_cCodSbs_IXN ON #t02(cCodSbs)	
	--------------------****************************************************************************
		
	------------------------CURSOR-----------------------------------
		Declare @ccodcred varchar(18), @diaatr int
		--set @ccodcred = '107016101000146483'
			Declare cDiaAtraso CURSOR FOR	
				select cCodCtaCre from #t02 (NOLOCK) 	

			OPEN cDiaAtraso
				FETCH cDiaAtraso into @ccodcred
				WHILE (@@FETCH_STATUS=0)
				BEGIN	

				set @diaatr = ( SELECT round(avg(cast(nDiaVenCuo as float)),0)
								FROM [KPYDPLANPAGCRE] PLA (NOLOCK)
								WHERE PLA.cCodCtaCre = @ccodcred )
			
				UPDATE #t02
				SET PromDiaAtr = @diaatr
				WHERE cCodCtaCre = @ccodcred	

				FETCH cDiaAtraso INTO @ccodcred
				END
				CLOSE cDiaAtraso
				DEALLOCATE cDiaAtraso

	----------------VERIFICANDO---------------------------
	SELECT * FROM #t02
	SELECT * FROM #t02 WHERE PromDiaAtr <= 6 ORDER BY dFecReg

	-- Drop table #t03
	SELECT * into #t03 FROM ( SELECT * FROM #t02 
								WHERE PromDiaAtr <= 6 ) AS TMP49 --(29647 row(s) affected)

	SELECT * FROM #t03 order by dFecReg

	SELECT distinct cCodSbs 
	FROM #t03 
	where cCodSbs != ''
	order by cCodSbs

	--*********************************INDEXANDO****************************************************
	CREATE NONCLUSTERED INDEX #t03_cCodCtaCre_IXN ON #t03(cCodCtaCre)
	CREATE NONCLUSTERED INDEX #t03_cCodSbs_IXN ON #t03(cCodSbs)	
	--------------------****************************************************************************
----------------------------------------------------------------------------------------------

		SELECT * FROM CRICMACHYO_DIARIO.DBO.urirccmae where CNUDOCI = '43111949' --0076639469


		Select top 50 *
		from CRICMACHYO_DIARIO.DBO.urirccsal
		Where left(CCTACON,4) 
				in ('1411','1413','1414','1415','1416','1421','1423','1424','1425','1426')
				and CCODEMP = '00107' 
		Order by CCODSBS
		
		-----------------CLIENTES QUE TRABAJAN CON CAJA HUANCAYO-----------------------------------------------------------------------
		
		Select A.CCODSBS, A.CCODEMP, count(A.CCODEMP) as 'Ent', left(A.CCTACON,4) as 'Cuenta'
				
		from CRICMACHYO_DIARIO.DBO.[urirccsal] A (nolock)
				INNER JOIN #t03 B 
					on B.cCodSbs = A.CCODSBS 
		group by A.CCODSBS, A.CCODEMP, A.CCTACON
		having count(A.CCODEMP)= 1
				and A.CCODEMP = '00107' 
				and left(A.CCTACON,4) 
					in ('1411','1413','1414','1415','1416','1421','1423','1424','1425','1426')			
				and A.CCODSBS not in
					(select CCODSBS from CRICMACHYO_DIARIO.DBO.urirccsal (nolock)
					  where  CCODEMP != '00107' 
						and left(CCTACON,4) in 
						('1411','1413','1414','1415','1416','1421','1423','1424','1425','1426')	)

		--Order by CCODSBS		
		--	( 8,076 row(s) affected)
	
		

