	SELECT   CLIM.cCodSbs 
	 , A.CMESPRO as 'Abr15', A.CCLAFIN as 'CaliAbr15', B.CMESPRO as 'Mar15', B.CCLAFIN as 'CaliMar15'
	 ,C.CMESPRO as 'Feb15', C.CCLAFIN as 'CaliFeb15', D.CMESPRO as 'Ene15', D.CCLAFIN as 'CaliEne15'
	 ,E.CMESPRO as 'Dic14', E.CCLAFIN as 'CaliDic14', F.CMESPRO as 'Nov14', F.CCLAFIN as 'CaliNov14'
	 ,G.CMESPRO as 'Oct14', G.CCLAFIN as 'CaliOct14', H.CMESPRO as 'Sep14', H.CCLAFIN as 'CaliSep14'
	 ,I.CMESPRO as 'Ago14', I.CCLAFIN as 'CaliAgo14', J.CMESPRO as 'Jul14', J.CCLAFIN as 'CaliJul14'
	 ,K.CMESPRO as 'Jun14', K.CCLAFIN as 'CaliJun14', L.CMESPRO as 'May14', L.CCLAFIN as 'CaliMay14'			
			FROM CMACHYOCLI_MANIANA.dbo.[CLIMCLIENTES] CLIM 
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae A 
						ON CLIM.cCodSbs =  A.CCODSBS 
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_1 B
						ON CLIM.cCodSbs = B.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_2 C
						ON CLIM.cCodSbs = C.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_3 D
						ON CLIM.cCodSbs = D.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_4 E
						ON CLIM.cCodSbs = E.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_5 F
						ON CLIM.cCodSbs = F.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_6 G
						ON CLIM.cCodSbs = G.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_7 H
						ON CLIM.cCodSbs = H.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_8 I
						ON CLIM.cCodSbs = I.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_9 J
						ON CLIM.cCodSbs = J.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_10 K
						ON CLIM.cCodSbs = K.CCODSBS
					LEFT JOIN CRICMACHYO_DIARIO.DBO.urirccmae_11 L
						ON CLIM.cCodSbs = L.CCODSBS			
